use serde_json::json;

/// Test that demonstrates enum serialization function naming patterns
///
/// This verifies that g2h generates field-specific serialization functions
/// that prevent enum value conflicts between different enum types.
#[test]
fn test_field_specific_serializer_patterns() {
    // Test that field-specific function names follow expected patterns
    let field_patterns = vec![
        ("payment_status", "PaymentStatus", "Single"),
        ("auth_status", "AuthenticationStatus", "Single"),
        ("processing_status", "ProcessingStatus", "Single"),
        ("optional_payment", "PaymentStatus", "Option"),
        ("auth_history", "AuthenticationStatus", "Repeated"),
        ("processing_steps", "ProcessingStatus", "Repeated"),
    ];

    for (field_name, enum_type, field_type) in field_patterns {
        let message_name = "conflict_test_request";
        let field_id = format!("{}_{}", message_name, field_name);

        let expected_functions = match field_type {
            "Single" => vec![
                format!("serialize_{}_as_string", field_id),
                format!("deserialize_{}_from_string", field_id),
            ],
            "Option" => vec![
                format!("serialize_option_{}_as_string", field_id),
                format!("deserialize_option_{}_from_string", field_id),
            ],
            "Repeated" => vec![
                format!("serialize_repeated_{}_as_string", field_id),
                format!("deserialize_repeated_{}_from_string", field_id),
            ],
            _ => panic!("Unknown field type: {}", field_type),
        };

        // Verify function names are type-specific
        for func_name in expected_functions {
            assert!(
                func_name.contains(&field_id),
                "Function {} should contain field ID {}",
                func_name,
                field_id
            );
            assert!(
                func_name.contains("_as_string") || func_name.contains("_from_string"),
                "Function {} should be a serializer/deserializer",
                func_name
            );
        }

        println!(
            "✅ Field {} ({}) generates correct function names",
            field_name, enum_type
        );
    }
}

/// Test enum value conflict scenarios  
///
/// This simulates the original problem: multiple enums with same values
/// should be handled by field-specific serializers
#[test]
fn test_enum_value_conflicts() {
    // Simulate enum value conflicts that the field-specific serializers solve
    let enum_conflicts = vec![
        // (enum_name, value, expected_string)
        ("PaymentStatus", 0, "SUCCESS"),
        ("PaymentStatus", 1, "PENDING"),
        ("PaymentStatus", 2, "FAILED"),
        ("AuthenticationStatus", 0, "AUTHENTICATION_SUCCESS"),
        ("AuthenticationStatus", 1, "AUTHENTICATION_PENDING"), // Same value as PaymentStatus::PENDING
        ("AuthenticationStatus", 2, "AUTHENTICATION_FAILED"), // Same value as PaymentStatus::FAILED
        ("ProcessingStatus", 0, "COMPLETED"),                 // Same value as SUCCESS
        ("ProcessingStatus", 1, "PROCESSING"), // Same value as PENDING/AUTHENTICATION_PENDING
        ("ProcessingStatus", 2, "ERROR"),      // Same value as FAILED/AUTHENTICATION_FAILED
    ];

    // Verify that the same integer value maps to different strings for different enums
    let value_1_mappings: Vec<(&str, &str)> = enum_conflicts
        .iter()
        .filter(|(_, value, _)| *value == 1)
        .map(|(enum_name, _, expected)| (*enum_name, *expected))
        .collect();

    assert_eq!(
        value_1_mappings.len(),
        3,
        "Should have 3 different enums with value 1"
    );
    assert_eq!(value_1_mappings[0], ("PaymentStatus", "PENDING"));
    assert_eq!(
        value_1_mappings[1],
        ("AuthenticationStatus", "AUTHENTICATION_PENDING")
    );
    assert_eq!(value_1_mappings[2], ("ProcessingStatus", "PROCESSING"));

    println!("✅ Enum value conflict test passed!");
    println!("Value 1 maps to different strings for different enum types:");
    for (enum_name, string_val) in value_1_mappings {
        println!("  - {}: {}", enum_name, string_val);
    }
}

/// Test the core benefit: field-specific serializers prevent wrong enum selection
#[test]
fn test_field_specific_serialization_benefit() {
    // Before the fix: generic serializer would try all enums and return first match
    // After the fix: field-specific serializer knows exactly which enum to use

    let test_scenarios = vec![
        // (field_name, enum_type, value, expected_serialized_string)
        ("payment_status", "PaymentStatus", 1, "PENDING"),
        (
            "auth_status",
            "AuthenticationStatus",
            1,
            "AUTHENTICATION_PENDING",
        ), // NOT "PENDING" or "DISCOVER"
        ("processing_status", "ProcessingStatus", 1, "PROCESSING"), // NOT "PENDING" or "AUTHENTICATION_PENDING"
    ];

    for (field_name, enum_type, value, expected) in test_scenarios {
        // Verify that each field gets its own specific serializer function name
        let field_id = format!("conflict_test_request_{}", field_name);
        let serialize_func = format!("serialize_{}_as_string", field_id);
        let deserialize_func = format!("deserialize_{}_from_string", field_id);

        // Function names should be field-specific to prevent conflicts
        assert!(
            serialize_func.contains("conflict_test_request"),
            "Serializer should be message-specific: {}",
            serialize_func
        );
        assert!(
            serialize_func.contains(field_name),
            "Serializer should be field-specific: {}",
            serialize_func
        );

        println!(
            "✅ Field {} ({}) value {} -> {} with functions {} / {}",
            field_name, enum_type, value, expected, serialize_func, deserialize_func
        );
    }

    println!("✅ Field-specific serialization benefit test passed!");
}

/// Test JSON serialization patterns that would be generated
#[test]
fn test_expected_json_patterns() {
    // Test the JSON patterns that should be generated with field-specific serializers
    let test_cases = vec![
        // Scenario 1: All enums have value 1 - should serialize to different strings
        (
            json!({
                "payment_status": 1,
                "auth_status": 1,
                "processing_status": 1
            }),
            vec![
                ("payment_status", "PENDING"),
                ("auth_status", "AUTHENTICATION_PENDING"), // The key fix: not "DISCOVER"
                ("processing_status", "PROCESSING"),
            ],
        ),
        // Scenario 2: Mixed values
        (
            json!({
                "payment_status": 0,
                "auth_status": 2,
                "processing_status": 1
            }),
            vec![
                ("payment_status", "SUCCESS"),
                ("auth_status", "AUTHENTICATION_FAILED"),
                ("processing_status", "PROCESSING"),
            ],
        ),
    ];

    for (input_json, expected_mappings) in test_cases {
        for (field_name, expected_string) in expected_mappings {
            let input_value = input_json[field_name].as_i64().unwrap();
            println!(
                "Field {} with value {} should serialize to {}",
                field_name, input_value, expected_string
            );

            // The key insight: same value (like 1) produces different strings
            // for different fields because each field has its own enum type
        }
    }

    println!("✅ Expected JSON patterns test passed!");
}

/// Tests for g2h internal enum processing logic
///
/// These tests verify that the enum field extraction and path resolution
/// work correctly for different protobuf structures.
#[cfg(test)]
mod g2h_tests {

    /// Test enum path resolution logic similar to g2h's resolve_enum_path
    fn resolve_enum_path(enum_type: &str) -> String {
        if enum_type.is_empty() || !enum_type.contains('.') {
            return enum_type.to_string();
        }

        let parts: Vec<&str> = enum_type.split('.').collect();

        match parts.len() {
            0 | 1 => parts.last().unwrap_or(&"UnknownEnum").to_string(),
            2 => {
                // Package-level enum like "package.EnumName"
                parts[1].to_string()
            }
            _ => {
                // Three or more parts like "package.Message.EnumName" or "ucs.v2.Currency"
                let potential_parent = parts[parts.len() - 2];
                let enum_name = parts[parts.len() - 1];

                // Check if parent looks like a message (PascalCase) vs a package component
                if is_message_name(potential_parent) {
                    // Message-nested enum: "package.Message.EnumName" -> "message::EnumName"
                    format!("{}::{}", to_snake_case(potential_parent), enum_name)
                } else {
                    // Package-level enum: "ucs.v2.Currency" -> "Currency"
                    enum_name.to_string()
                }
            }
        }
    }

    fn is_message_name(name: &str) -> bool {
        name.chars().next().is_some_and(|c| c.is_uppercase())
    }

    fn to_snake_case(input: &str) -> String {
        use heck::ToSnakeCase;
        input.to_snake_case()
    }

    #[test]
    fn test_enum_path_resolution() {
        // Test cases covering different protobuf enum path structures
        let test_cases = vec![
            // Simple enum name
            ("PaymentStatus", "PaymentStatus"),
            // Package-level enum
            ("hello_world.PaymentStatus", "PaymentStatus"),
            ("ucs.v2.Currency", "Currency"),
            ("package.EnumName", "EnumName"),
            // Message-nested enum (PascalCase parent)
            (
                "hello_world.HelloReply.ResponseStatus",
                "hello_reply::ResponseStatus",
            ),
            (
                "package.UserProfile.AccountStatus",
                "user_profile::AccountStatus",
            ),
            (
                "test.PaymentRequest.PaymentType",
                "payment_request::PaymentType",
            ),
            // Edge cases
            ("", ""),
            ("single", "single"),
            ("a.b", "b"),
            (
                "namespace.v1.service.MessageName.EnumName",
                "message_name::EnumName",
            ),
        ];

        for (input, expected) in test_cases {
            let result = resolve_enum_path(input);
            assert_eq!(result, expected, "Failed for input: '{}'", input);
        }

        println!("✅ Enum path resolution tests passed!");
    }

    #[test]
    fn test_message_name_detection() {
        let test_cases = vec![
            ("HelloReply", true),     // PascalCase message
            ("PaymentRequest", true), // PascalCase message
            ("UserProfile", true),    // PascalCase message
            ("v2", false),            // Package component
            ("ucs", false),           // Package component
            ("hello_world", false),   // Package component
            ("", false),              // Empty string
            ("lowercase", false),     // Lowercase
            ("UPPERCASE", true),      // All uppercase (treated as message)
            ("mixedCase", false),     // camelCase (not PascalCase)
        ];

        for (input, expected) in test_cases {
            let result = is_message_name(input);
            assert_eq!(result, expected, "Failed for input: '{}'", input);
        }

        println!("✅ Message name detection tests passed!");
    }

    #[test]
    fn test_snake_case_conversion() {
        let test_cases = vec![
            ("HelloReply", "hello_reply"),
            ("PaymentRequest", "payment_request"),
            ("UserProfile", "user_profile"),
            ("ResponseStatus", "response_status"),
            ("XMLHttpRequest", "xml_http_request"), // heck produces better output
            ("APIKey", "api_key"),                  // heck produces better output
            ("lowercase", "lowercase"),
            ("", ""),
            ("A", "a"),
            ("AB", "ab"), // heck produces better output
        ];

        for (input, expected) in test_cases {
            let result = to_snake_case(input);
            assert_eq!(result, expected, "Failed for input: '{}'", input);
        }

        println!("✅ Snake case conversion tests passed!");
    }

    /// Test that simulates the enum field extraction process
    #[test]
    fn test_enum_field_extraction_simulation() {
        // Simulate the data structure that extract_enum_fields_from_message_static would create
        // ConflictTestRequest fields
        let extracted_fields = vec![
            (
                "conflict_test_request_payment_status".to_string(),
                "PaymentStatus".to_string(),
                "Single".to_string(),
            ),
            (
                "conflict_test_request_auth_status".to_string(),
                "AuthenticationStatus".to_string(),
                "Single".to_string(),
            ),
            (
                "conflict_test_request_processing_status".to_string(),
                "ProcessingStatus".to_string(),
                "Single".to_string(),
            ),
            (
                "conflict_test_request_optional_payment".to_string(),
                "PaymentStatus".to_string(),
                "Option".to_string(),
            ),
            (
                "conflict_test_request_auth_history".to_string(),
                "AuthenticationStatus".to_string(),
                "Repeated".to_string(),
            ),
            (
                "conflict_test_request_processing_steps".to_string(),
                "ProcessingStatus".to_string(),
                "Repeated".to_string(),
            ),
            // HelloReply nested enum
            (
                "hello_reply_status".to_string(),
                "hello_reply::ResponseStatus".to_string(),
                "Single".to_string(),
            ),
        ];

        // Verify field ID generation follows expected pattern
        assert!(extracted_fields
            .iter()
            .any(|(field_id, _, _)| field_id == "conflict_test_request_payment_status"));
        assert!(extracted_fields
            .iter()
            .any(|(field_id, _, _)| field_id == "conflict_test_request_auth_status"));

        // Verify enum type resolution
        let payment_enum = extracted_fields
            .iter()
            .find(|(field_id, _, _)| field_id == "conflict_test_request_payment_status");
        assert_eq!(payment_enum.unwrap().1, "PaymentStatus");

        let auth_enum = extracted_fields
            .iter()
            .find(|(field_id, _, _)| field_id == "conflict_test_request_auth_status");
        assert_eq!(auth_enum.unwrap().1, "AuthenticationStatus");

        // Verify nested enum path
        let nested_enum = extracted_fields
            .iter()
            .find(|(field_id, _, _)| field_id == "hello_reply_status");
        assert_eq!(nested_enum.unwrap().1, "hello_reply::ResponseStatus");

        // Verify field labels
        let optional_field = extracted_fields
            .iter()
            .find(|(field_id, _, _)| field_id == "conflict_test_request_optional_payment");
        assert_eq!(optional_field.unwrap().2, "Option");

        let repeated_field = extracted_fields
            .iter()
            .find(|(field_id, _, _)| field_id == "conflict_test_request_auth_history");
        assert_eq!(repeated_field.unwrap().2, "Repeated");

        println!("✅ Enum field extraction simulation test passed!");
        println!("Extracted {} enum fields:", extracted_fields.len());
        for (field_id, enum_type, field_label) in &extracted_fields {
            println!("  - {}: {} ({})", field_id, enum_type, field_label);
        }
    }

    /// Test that verifies the generated function names follow the expected pattern
    #[test]
    fn test_generated_function_names() {
        let test_cases = vec![
            (
                "conflict_test_request_payment_status",
                "Single",
                vec![
                    "serialize_conflict_test_request_payment_status_as_string",
                    "deserialize_conflict_test_request_payment_status_from_string",
                ],
            ),
            (
                "conflict_test_request_optional_payment",
                "Option",
                vec![
                    "serialize_option_conflict_test_request_optional_payment_as_string",
                    "deserialize_option_conflict_test_request_optional_payment_from_string",
                ],
            ),
            (
                "conflict_test_request_auth_history",
                "Repeated",
                vec![
                    "serialize_repeated_conflict_test_request_auth_history_as_string",
                    "deserialize_repeated_conflict_test_request_auth_history_from_string",
                ],
            ),
        ];

        for (field_id, field_label, expected_functions) in test_cases {
            match field_label {
                "Single" => {
                    let serialize_fn = format!("serialize_{}_as_string", field_id);
                    let deserialize_fn = format!("deserialize_{}_from_string", field_id);
                    assert_eq!(serialize_fn, expected_functions[0]);
                    assert_eq!(deserialize_fn, expected_functions[1]);
                }
                "Option" => {
                    let serialize_fn = format!("serialize_option_{}_as_string", field_id);
                    let deserialize_fn = format!("deserialize_option_{}_from_string", field_id);
                    assert_eq!(serialize_fn, expected_functions[0]);
                    assert_eq!(deserialize_fn, expected_functions[1]);
                }
                "Repeated" => {
                    let serialize_fn = format!("serialize_repeated_{}_as_string", field_id);
                    let deserialize_fn = format!("deserialize_repeated_{}_from_string", field_id);
                    assert_eq!(serialize_fn, expected_functions[0]);
                    assert_eq!(deserialize_fn, expected_functions[1]);
                }
                _ => panic!("Unexpected field label: {}", field_label),
            }
        }

        println!("✅ Generated function names test passed!");
    }
}

/// Test that verifies the actual generated code contains field-specific enum serializers
///
/// This test reads the generated protobuf code to ensure that g2h actually
/// created the field-specific serialization functions we expect.
use std::fs;
use std::path::Path;

#[test]
fn test_generated_code_contains_field_specific_serializers() {
    // Find the generated protobuf file
    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR not set");
    let generated_file = Path::new(&out_dir).join("hello_world.rs");

    assert!(
        generated_file.exists(),
        "Generated file should exist: {:?}",
        generated_file
    );

    let generated_code =
        fs::read_to_string(&generated_file).expect("Should be able to read generated file");

    // Verify that field-specific serializers are generated
    let expected_functions = vec![
        // ConflictTestRequest field serializers
        "serialize_conflict_test_request_payment_status_as_string",
        "deserialize_conflict_test_request_payment_status_from_string",
        "serialize_conflict_test_request_auth_status_as_string",
        "deserialize_conflict_test_request_auth_status_from_string",
        "serialize_conflict_test_request_processing_status_as_string",
        "deserialize_conflict_test_request_processing_status_from_string",
        // Optional field serializers
        "serialize_option_conflict_test_request_optional_payment_as_string",
        "deserialize_option_conflict_test_request_optional_payment_from_string",
        // Repeated field serializers
        "serialize_repeated_conflict_test_request_auth_history_as_string",
        "deserialize_repeated_conflict_test_request_auth_history_from_string",
        "serialize_repeated_conflict_test_request_processing_steps_as_string",
        "deserialize_repeated_conflict_test_request_processing_steps_from_string",
        // Other field serializers
        "serialize_hello_request_greeting_type_as_string",
        "serialize_hello_reply_status_as_string",
        "serialize_payment_response_status_as_string",
    ];

    for expected_function in expected_functions {
        assert!(
            generated_code.contains(expected_function),
            "Generated code should contain function: {}",
            expected_function
        );
        println!("✅ Found expected function: {}", expected_function);
    }

    // Verify that the functions are type-specific (use the correct enum types)
    let type_specific_checks = vec![
        (
            "serialize_conflict_test_request_payment_status_as_string",
            "PaymentStatus::try_from",
        ),
        (
            "serialize_conflict_test_request_auth_status_as_string",
            "AuthenticationStatus::try_from",
        ),
        (
            "serialize_conflict_test_request_processing_status_as_string",
            "ProcessingStatus::try_from",
        ),
        (
            "deserialize_conflict_test_request_payment_status_from_string",
            "PaymentStatus::from_str_name",
        ),
        (
            "deserialize_conflict_test_request_auth_status_from_string",
            "AuthenticationStatus::from_str_name",
        ),
        (
            "deserialize_conflict_test_request_processing_status_from_string",
            "ProcessingStatus::from_str_name",
        ),
    ];

    for (function_name, expected_enum_usage) in type_specific_checks {
        // Find the function definition (not just the serde attribute)
        let function_def_pattern = format!("pub fn {}", function_name);
        if let Some(function_start) = generated_code.find(&function_def_pattern) {
            // Look for the next function or end of module
            let function_end = generated_code[function_start..]
                .find("\n    #[allow(dead_code)]\n    pub fn ")
                .unwrap_or_else(|| generated_code[function_start..].find("\n}").unwrap_or(2000));
            let function_code = &generated_code[function_start..function_start + function_end];

            assert!(
                function_code.contains(expected_enum_usage),
                "Function {} should use {}, but doesn't in its implementation",
                function_name,
                expected_enum_usage
            );

            println!(
                "✅ Function {} correctly uses {}",
                function_name, expected_enum_usage
            );
        } else {
            println!(
                "⚠️  Could not find function definition for {}",
                function_name
            );
        }
    }

    // Verify the enum_deserializer module exists
    assert!(
        generated_code.contains("pub mod enum_deserializer"),
        "Generated code should contain enum_deserializer module"
    );

    // Verify that the serde attributes reference the correct functions
    let serde_attribute_checks = vec![
        (
            "payment_status",
            "serialize_conflict_test_request_payment_status_as_string",
        ),
        (
            "auth_status",
            "serialize_conflict_test_request_auth_status_as_string",
        ),
        (
            "processing_status",
            "serialize_conflict_test_request_processing_status_as_string",
        ),
    ];

    for (field_name, expected_serializer) in serde_attribute_checks {
        // Look for the serde attribute in the struct definition
        let field_pattern = format!("pub {}: i32", field_name);
        if let Some(field_pos) = generated_code.find(&field_pattern) {
            // Look backwards for the serde attribute
            let preceding_code = &generated_code[field_pos.saturating_sub(500)..field_pos];
            assert!(
                preceding_code.contains(expected_serializer),
                "Field {} should have serde attribute referencing {}",
                field_name,
                expected_serializer
            );

            println!(
                "✅ Field {} has correct serde attribute for {}",
                field_name, expected_serializer
            );
        }
    }

    println!("✅ Generated code verification passed!");
    println!("Generated file: {:?}", generated_file);
    println!("Total generated code size: {} bytes", generated_code.len());
}

